window.ScripturaLexicons.BDAG_PART_0011 = {source:"BDAG", searchAnchorId:"bdag-search-anchor", entryAnchorId:"bdag-entry-anchor", rowsHtml:"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-adikeo-bdag\" data-source=\"BDAG\" data-search=\"ἀδικέω adikeo cometer injustiça errar tratar injustamente prejudicar danificar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀδικέω</td><td>Verbo</td><td>agir injustamente; fazer mal; prejudicar</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-adikema-bdag\" data-source=\"BDAG\" data-search=\"ἀδίκημα adikema injustiça crime delito dano maus-tratos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀδίκημα</td><td>Substantivo</td><td>injustiça; crime; delito; maus-tratos</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-adikia-bdag\" data-source=\"BDAG\" data-search=\"ἀδικία adikia injustiça iniquidade maldade erro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀδικία</td><td>Substantivo</td><td>injustiça; iniquidade; maldade</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-adikokrites-bdag\" data-source=\"BDAG\" data-search=\"ἀδικοκρίτης adikokrites juiz injusto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀδικοκρίτης</td><td>Substantivo</td><td>juiz injusto</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-adikos-bdag\" data-source=\"BDAG\" data-search=\"ἄδικος adikos injusto desonesto ímpio associado injustiça BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἄδικος</td><td>Adjetivo</td><td>injusto; desonesto; ímpio</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-adikos-adv-bdag\" data-source=\"BDAG\" data-search=\"ἀδίκως adikos advérbio injustamente imerecidamente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀδίκως</td><td>Advérbio</td><td>injustamente; imerecidamente</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-adistaktos-adv-bdag\" data-source=\"BDAG\" data-search=\"ἀδιστάκτως adistaktos advérbio sem duvidar sem hesitar seguramente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀδιστάκτως</td><td>Advérbio</td><td>sem duvidar; sem hesitar; seguramente</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-admin-bdag\" data-source=\"BDAG\" data-search=\"Ἀδμίν Admin genealogia Jesus Arni BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἀδμίν</td><td>Nome próprio</td><td>Admin</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-adokimos-bdag\" data-source=\"BDAG\" data-search=\"ἀδόκιμος adokimos reprovado desaprovado sem valor indigno impróprio incapaz BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀδόκιμος</td><td>Adjetivo</td><td>reprovado; sem valor; indigno; impróprio</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-adolos-bdag\" data-source=\"BDAG\" data-search=\"ἄδολος adolos sem dolo puro não adulterado leite BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἄδολος</td><td>Adjetivo</td><td>sem dolo; não adulterado; puro</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-adoxos-bdag\" data-source=\"BDAG\" data-search=\"ἄδοξος adoxos sem reputação obscuro sem honra BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἄδοξος</td><td>Adjetivo</td><td>sem reputação; obscuro</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-adramyttenos-bdag\" data-source=\"BDAG\" data-search=\"Ἀδραμυττηνός Adramyttenos Adramítio Adramyttium Mísia Ásia Menor BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἀδραμυττηνός</td><td>Adjetivo gentílico</td><td>de Adramítio</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-adranes-bdag\" data-source=\"BDAG\" data-search=\"ἀδρανής adranes impotente sem força ineficaz BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀδρανής</td><td>Adjetivo</td><td>sem força; impotente</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-adrias-bdag\" data-source=\"BDAG\" data-search=\"Ἀδρίας Adrias mar Adriático BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἀδρίας</td><td>Nome próprio</td><td>mar Adriático</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hadrotes-bdag\" data-source=\"BDAG\" data-search=\"ἁδρότης hadrotes abundância generosidade dádiva abundante BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἁδρότης</td><td>Substantivo</td><td>abundância; generosidade</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-adunateo-bdag\" data-source=\"BDAG\" data-search=\"ἀδυνατέω adunateo ser impossível impotente incapaz BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀδυνατέω</td><td>Verbo</td><td>ser impossível; ser incapaz</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-adunatos-bdag\" data-source=\"BDAG\" data-search=\"ἀδύνατος adunatos incapaz impotente impossível fraco BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀδύνατος</td><td>Adjetivo/Substantivo</td><td>incapaz; impotente; impossível</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-adusbastaktos-bdag\" data-source=\"BDAG\" data-search=\"ἀδυσβάστακτος adusbastaktos não demasiado difícil suportar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀδυσβάστακτος</td><td>Adjetivo</td><td>não demasiado difícil de suportar</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-ado-bdag\" data-source=\"BDAG\" data-search=\"ᾂδω ado cantar louvor cantar hino BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ᾂδω</td><td>Verbo</td><td>cantar; cantar em louvor</td><td><span class=\"source-pill\">BDAG</span></td></tr>", cardsHtml:"<article id=\"entry-adikeo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀδικέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦adikéō⟧</span><span class=\"separator\">·</span><span class=\"greek\">fut. ἀδικήσω; 1 aor. ἠδίκησα; pf. ἠδίκηκα · pass. fut. ἀδικηθήσεται; 1 aor. ἠδικήθην; pf. ptc. ἠδικημένος</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀδικηθήσεται\" data-meanings=\"será prejudicado; será tratado injustamente\">ἀδικηθήσεται</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PRO.17.8\" target=\"_blank\" rel=\"noopener noreferrer\">Pv 17.8</a> v.l.; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἠδικημένος\" data-meanings=\"tendo sido injustiçado\">ἠδικημένος</span> LXX. Desde os Hinos Homéricos.)\n<span class=\"sense-number\">1.</span> <strong>Agir de maneira injusta, fazer o mal.</strong>\n<strong>a.</strong> Intransitivo, da violação de lei humana ou divina (definido em Aristóteles, <em>Rhet.</em> 1, 10: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἔστι τὸ ἀδικεῖν τὸ βλάπτειν ἑκόντα παρὰ τὸν νόμον\" data-meanings=\"agir injustamente é prejudicar voluntariamente contra a lei\">ἔστι τὸ ἀδικεῖν τὸ βλάπτειν ἑκόντα παρὰ τὸν νόμον</span>; Fílon, <em>Dec.</em> 66; Hippol., <em>Ref.</em> 9, 15, 6): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὁ ἀδικῶν\" data-meanings=\"o que pratica injustiça; malfeitor\">ὁ ἀδικῶν</span> (SIG 635, 22); <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὁ ἀδικῶν ἀδικησάτω ἔτι\" data-meanings=\"quem pratica injustiça, pratique injustiça ainda\">ὁ ἀδικῶν ἀδικησάτω ἔτι</span>, isto é, tal pessoa está agora além de redenção, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.22.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 22.11</a>. Compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.25\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 3.25</a>; também <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"κομίσεται ὃ ἠδίκησεν\" data-meanings=\"receberá a recompensa do mal que fez\">κομίσεται ὃ ἠδίκησεν</span>.\n<strong>b.</strong> Intransitivo, <strong>estar errado, estar em falta</strong> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/EXO.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">Êx 2.13</a>): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εἰ ἀδικῶ\" data-meanings=\"se estou errado; se fiz mal\">εἰ ἀδικῶ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.11\" target=\"_blank\" rel=\"noopener noreferrer\">At 25.11</a>.\n<strong>c.</strong> Transitivo, <strong>fazer mal a alguém, tratar alguém injustamente</strong>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οὐκ ἀδικῶ σε\" data-meanings=\"não te trato injustamente; não te engano\">οὐκ ἀδικῶ σε</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20.13</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἱνατί ἀδικεῖτε ἀλλήλους;\" data-meanings=\"por que vos prejudicais mutuamente?\">ἱνατί ἀδικεῖτε ἀλλήλους;</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.26\" target=\"_blank\" rel=\"noopener noreferrer\">At 7.26</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὸν πλησίον\" data-meanings=\"o próximo\">τὸν πλησίον</span> v. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.27\" target=\"_blank\" rel=\"noopener noreferrer\">27</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οὐδένα\" data-meanings=\"ninguém\">οὐδένα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Co 7.2</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀδελφούς\" data-meanings=\"irmãos\">ἀδελφούς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 6.8</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"νηπίους\" data-meanings=\"crianças\">νηπίους</span> 1 Cl 57:7 (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PRO.1.32\" target=\"_blank\" rel=\"noopener noreferrer\">Pv 1.32</a>). Com acusativo subentendido, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.12\" target=\"_blank\" rel=\"noopener noreferrer\">2 Co 7.12a</a>. Com duplo acusativo: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οὐδέν με ἠδικήσατε\" data-meanings=\"não me fizestes mal algum\">οὐδέν με ἠδικήσατε</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 4.12</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.10\" target=\"_blank\" rel=\"noopener noreferrer\">At 25.10</a>; MPol 9:3. Passivo: <strong>ser injustiçado, ser tratado injustamente</strong>, 1 Cl 8:4 (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/ISA.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">Is 1.17</a>); Dg 6:5; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἰδών τινα ἀδικούμενον\" data-meanings=\"vendo alguém ser injustiçado\">ἰδών τινα ἀδικούμενον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.24\" target=\"_blank\" rel=\"noopener noreferrer\">At 7.24</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὁ ἀδικηθείς\" data-meanings=\"o que foi injustiçado\">ὁ ἀδικηθείς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.12\" target=\"_blank\" rel=\"noopener noreferrer\">2 Co 7.12b</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τίς πλέον ἀδικηθῇ;\" data-meanings=\"quem sofreu maior injustiça?\">τίς πλέον ἀδικηθῇ;</span> IEph 10:3; <strong>deixar-se injustiçar</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 6.7</a>.\n<span class=\"sense-number\">2.</span> <strong>Causar dano a ou maltratar, prejudicar</strong>, com acusativo de pessoa: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"με\" data-meanings=\"a mim\">με</span> IRo 1:2; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τοὺς ἀνθρώπους\" data-meanings=\"as pessoas\">τοὺς ἀνθρώπους</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 9.10</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αὐτούς\" data-meanings=\"a eles\">αὐτούς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.5\" target=\"_blank\" rel=\"noopener noreferrer\">11.5</a>. Com acusativo de coisa, <strong>danificar, estragar</strong>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὴν γῆν\" data-meanings=\"a terra\">τὴν γῆν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.7.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 7.2 s.</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὸν χόρτον τῆς γῆς\" data-meanings=\"a erva da terra\">τὸν χόρτον τῆς γῆς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.4\" target=\"_blank\" rel=\"noopener noreferrer\">9.4</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὸ ἔλαιον καὶ τὸν οἶνον\" data-meanings=\"o azeite e o vinho\">τὸ ἔλαιον καὶ τὸν οἶνον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.6.6\" target=\"_blank\" rel=\"noopener noreferrer\">6.6</a>. Com duplo acusativo: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οὐδὲν ὑμᾶς οὐ μὴ ἀδικήσῃ\" data-meanings=\"nada de modo algum vos fará dano\">οὐδὲν ὑμᾶς οὐ μὴ ἀδικήσῃ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 10.19</a>; “se te causou alguma perda”, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHM.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">Fm 18</a>. Com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐν\" data-meanings=\"em; por meio de\">ἐν</span> do meio pelo qual o dano resulta: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐν αὐταῖς … ἀδικοῦσιν\" data-meanings=\"com elas [as caudas] causam dano\">ἐν αὐταῖς … ἀδικοῦσιν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 9.19</a>. Passivo seguido de <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐκ\" data-meanings=\"de; a partir de\">ἐκ</span> da fonte: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οὐ μὴ ἀδικηθῇ ἐκ τοῦ θανάτου τοῦ δευτέρου\" data-meanings=\"não será prejudicado pela segunda morte\">οὐ μὴ ἀδικηθῇ ἐκ τοῦ θανάτου τοῦ δευτέρου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 2.11</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀδικούμενοι μισθὸν ἀδικίας\" data-meanings=\"sendo defraudados quanto ao salário da injustiça\">ἀδικούμενοι μισθὸν ἀδικίας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pe 2.13</a> — as leituras variam e o texto é incerto. — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"δίκη\" data-meanings=\"justiça; direito\">δίκη</span>. M-M. TW.\n</p></section></article><article id=\"entry-adikema-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀδίκημα</h1><div class=\"entry-meta\"><span class=\"greek\">ατος, τό</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦adíkēma⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Heródoto+; inscrições, papiros, LXX, Enoque; TestJob 37:6; Fílon; Josefo; Just.; Ath.; Mel., <em>P.</em> 73, 534; 81, 597.)\n<span class=\"sense-number\">1.</span> <strong>Violação de normas de justiça, injustiça, crime, delito</strong> (Aristóteles, <em>EN</em> 5, 7; Appian, <em>Bell. Civ.</em> 4, 69 §292; Jos., <em>Ant.</em> 3, 321; 5, 234): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.14\" target=\"_blank\" rel=\"noopener noreferrer\">At 18.14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.20\" target=\"_blank\" rel=\"noopener noreferrer\">24.20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 18.5</a>.\n<span class=\"sense-number\">2.</span> <strong>Aquilo que causa dano ou lesão, maus-tratos</strong>, plural (En 13:2; Diod S 14, 2, 2; PHal 1, 193), IRo 5:1. — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"δίκη\" data-meanings=\"justiça; direito\">δίκη</span>. M-M. TW.\n</p></section></article><article id=\"entry-adikia-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀδικία</h1><div class=\"entry-meta\"><span class=\"greek\">ας, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦adikía⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Anaximandro, Heródoto+.)\n<span class=\"sense-number\">1.</span> <strong>Ato que viola padrões de conduta correta, injustiça, mau procedimento</strong> (oposto a <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"δικαιοσύνη\" data-meanings=\"justiça\">δικαιοσύνη</span>): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1.9</a> v.l. (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PSA.44.8\" target=\"_blank\" rel=\"noopener noreferrer\">Sl 44.8</a> v.l.); 2 Cl 19:2. Com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀνομία\" data-meanings=\"iniquidade; transgressão da lei\">ἀνομία</span> 1 Cl 35:5 v.l.; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"χαρίσασθέ μοι τὴν ἀδικίαν ταύτην\" data-meanings=\"perdoai-me esta injustiça\">χαρίσασθέ μοι τὴν ἀδικίαν ταύτην</span>, ironicamente, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Co 12.13</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀπέχεσθαι πάσης ἀ.\" data-meanings=\"abster-se de toda injustiça\">ἀπέχεσθαι πάσης ἀ.</span> Pol 2:2. No plural, <strong>más ações</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.12\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8.12</a> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/JER.31.34\" target=\"_blank\" rel=\"noopener noreferrer\">Jr 31.34</a>); com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀνομίαι\" data-meanings=\"iniquidades\">ἀνομίαι</span> e outros, 1 Cl 60:1.\n<span class=\"sense-number\">2.</span> <strong>Qualidade de injustiça, injustiça, iniquidade, maldade</strong>, Dg 9:1 s. É dita pecado, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.5.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Jo 5.17</a> (embora 1 também seja possível); por isso é impossível em Deus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.14\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 9.14</a>, e hostil à verdade: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐπὶ ἀδικίαν ἀνθρώπων τῶν τὴν ἀλήθειαν ἐν ἀ. κατεχόντων\" data-meanings=\"contra a injustiça dos homens que detêm a verdade na injustiça\">ἐπὶ ἀδικίαν ἀνθρώπων τῶν τὴν ἀλήθειαν ἐν ἀ. κατεχόντων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 1.18</a>; o mesmo contraste entre <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀ.\" data-meanings=\"injustiça\">ἀ.</span> e <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀληθής\" data-meanings=\"verdadeiro\">ἀληθής</span> em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.18\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 7.18</a>. Compare <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πείθεσθαι τῇ ἀ.\" data-meanings=\"obedecer à injustiça\">πείθεσθαι τῇ ἀ.</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 2.8</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"χαίρειν ἐπὶ τῇ ἀ.\" data-meanings=\"alegrar-se com a injustiça\">χαίρειν ἐπὶ τῇ ἀ.</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.13.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 13.6</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εὐδοκεῖν τῇ ἀ.\" data-meanings=\"ter prazer na injustiça\">εὐδοκεῖν τῇ ἀ.</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ts 2.12</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀφιστάναι ἀπὸ ἀ.\" data-meanings=\"afastar-se da injustiça\">ἀφιστάναι ἀπὸ ἀ.</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">2 Tm 2.19</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"καθαρίζειν ἡμᾶς ἀπὸ πάσης ἀ.\" data-meanings=\"purificar-nos de toda injustiça\">καθαρίζειν ἡμᾶς ἀπὸ πάσης ἀ.</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Jo 1.9</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πεπληρωμένος πάσῃ ἀ.\" data-meanings=\"cheio de toda injustiça\">πεπληρωμένος πάσῃ ἀ.</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.29\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 1.29</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">3.5</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐν πάσῃ ἀπάτῃ ἀδικίας\" data-meanings=\"com todo engano da injustiça\">ἐν πάσῃ ἀπάτῃ ἀδικίας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ts 2.10</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὅπλα ἀδικίας\" data-meanings=\"armas de injustiça\">ὅπλα ἀδικίας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 6.13</a>.\nO genitivo é frequente como nas línguas semíticas, mas também no grego não bíblico, em lugar de adjetivo. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"μισθὸς ἀ.\" data-meanings=\"salário injusto; recompensa da injustiça\">μισθὸς ἀ.</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pe 2.13</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">15</a>; em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">At 1.18</a>, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐκ μισθοῦ τῆς ἀ.\" data-meanings=\"com o salário da injustiça\">ἐκ μισθοῦ τῆς ἀ.</span> significa que Judas pagou o campo com o pagamento recebido por seu crime. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οἰκονόμος τῆς ἀ.\" data-meanings=\"administrador da injustiça\">οἰκονόμος τῆς ἀ.</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 16.8</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"κριτὴς τῆς ἀ.\" data-meanings=\"juiz da injustiça\">κριτὴς τῆς ἀ.</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.6\" target=\"_blank\" rel=\"noopener noreferrer\">18.6</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"μαμωνᾶς τῆς ἀ.\" data-meanings=\"mamom da injustiça\">μαμωνᾶς τῆς ἀ.</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.9\" target=\"_blank\" rel=\"noopener noreferrer\">16.9</a>. Num sentido mais amplo, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀ.\" data-meanings=\"injustiça\">ἀ.</span> pode designar a essência do mundo mau; nesse caso o genitivo assinala lealdade ou sujeição a ele: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 16.8</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.9\" target=\"_blank\" rel=\"noopener noreferrer\">9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.6\" target=\"_blank\" rel=\"noopener noreferrer\">18.6</a>. Sobre <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"κόσμος τῆς ἀ.\" data-meanings=\"mundo da injustiça\">κόσμος τῆς ἀ.</span> em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 3.6</a>, veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"κόσμος\" data-meanings=\"mundo\">κόσμος</span> 8; sobre <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"σύνδεσμος ἀ.\" data-meanings=\"vínculo da injustiça\">σύνδεσμος ἀ.</span> em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.23\" target=\"_blank\" rel=\"noopener noreferrer\">At 8.23</a>, veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"σύνδεσμος\" data-meanings=\"vínculo\">σύνδεσμος</span>; também B 3:3 (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/ISA.58.6\" target=\"_blank\" rel=\"noopener noreferrer\">Is 58.6</a>). Em <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐργάται ἀ.\" data-meanings=\"obreiros da injustiça\">ἐργάται ἀ.</span>, o genitivo representa o acusativo objeto = <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐργαζόμενοι τὴν ἀ.\" data-meanings=\"os que praticam injustiça\">ἐργαζόμενοι τὴν ἀ.</span>, “malfeitores”, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 13.27</a>. — B. van Groningen, “Ἀδικία”, <em>Mnemosyne</em>, n.s. 55, 1927, 260–262. — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"δίκη\" data-meanings=\"justiça; direito\">δίκη</span>. M-M. TW. Sv.\n</p></section></article><article id=\"entry-adikokrites-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀδικοκρίτης</h1><div class=\"entry-meta\"><span class=\"greek\">ου, ὁ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦adikokrítēs⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Oposto a <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"δικαιοκρίτης\" data-meanings=\"juiz justo\">δικαιοκρίτης</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/2MA.12.41\" target=\"_blank\" rel=\"noopener noreferrer\">2 Mc 12.41</a>; PRyl 113, 35 [séc. II d.C.]; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀδικοκρισία\" data-meanings=\"julgamento injusto\">ἀδικοκρισία</span> em Heph. Astr. [séc. IV d.C.] 3, 34: Cat. Cod. Astr. V 3 p. 81, 7.) <strong>Juiz injusto</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">Tt 1.9</a> v.l. — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"δίκη\" data-meanings=\"justiça\">δίκη</span> e <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"κρίνω\" data-meanings=\"julgar\">κρίνω</span>.\n</p></section></article><article id=\"entry-adikos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄδικος</h1><div class=\"entry-meta\"><span class=\"greek\">ον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦ádikos⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Hesíodo+.) “<strong>Injusto</strong>”.\n<span class=\"sense-number\">1.</span> <strong>Relativo a agir de modo contrário ao que é correto, injusto, desonesto</strong>, de pessoas: oposto a <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"δίκαιος\" data-meanings=\"justo\">δίκαιος</span> como cidadão-modelo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.45\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5.45</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.15\" target=\"_blank\" rel=\"noopener noreferrer\">At 24.15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pe 3.18</a>; Dg 9:2; Hm 6, 1, 1 s. Com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄνομος\" data-meanings=\"sem lei; transgressor\">ἄνομος</span>, 1 Cl 56:11 (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/JOB.5.22\" target=\"_blank\" rel=\"noopener noreferrer\">Jó 5.22</a>). Com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἅρπαγες\" data-meanings=\"rapaces\">ἅρπαγες</span> e <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"μοιχοί\" data-meanings=\"adúlteros\">μοιχοί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 18.11</a>. Negado de Deus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 3.5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.10\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6.10</a>. O <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄ.\" data-meanings=\"injusto\">ἄ.</span> é excluído do Reino, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 6.9</a>; os injustos tornam-se ricos, 2 Cl 20:1. Em declaração crítica não dos juízes seculares, mas da conduta litigiosa dos destinatários de Paulo, como indica o termo oposto <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἅγιοι\" data-meanings=\"santos\">ἅγιοι</span>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"κρίνεσθαι ἐπὶ τῶν ἄ.\" data-meanings=\"ir a juízo diante dos injustos\">κρίνεσθαι ἐπὶ τῶν ἄ.</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 6.1</a>. Em MPol 19:2, o julgamento de um procônsul é declarado injusto. Oposto a <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εὐσεβής\" data-meanings=\"piedoso\">εὐσεβής</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pe 2.9</a>; <strong>desonesto, não confiável</strong> (oposto a <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πιστός\" data-meanings=\"fiel\">πιστός</span>), <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὁ ἐν ἐλαχίστῳ ἄ. καὶ ἐν πολλῷ ἄ. ἐστιν\" data-meanings=\"quem é injusto no pouco também é injusto no muito\">ὁ ἐν ἐλαχίστῳ ἄ. καὶ ἐν πολλῷ ἄ. ἐστιν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.10\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 16.10</a>. De Satanás, AcPlCor 2:11.\n<span class=\"sense-number\">2.</span> <strong>Relativo a estar associado à injustiça, injusto</strong>, de coisas: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"μαμωνᾶς\" data-meanings=\"mamom\">μαμωνᾶς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 16.9</a> D, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.11\" target=\"_blank\" rel=\"noopener noreferrer\">11</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"κρίσις ἄ.\" data-meanings=\"julgamento injusto\">κρίσις ἄ.</span> (TestJos 14:1) Pol 6:1; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄ. βίος\" data-meanings=\"vida injusta\">ἄ. βίος</span> com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄνομος\" data-meanings=\"sem lei\">ἄνομος</span> MPol 3:1; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ζῆλος ἄ.\" data-meanings=\"ciúme injusto\">ζῆλος ἄ.</span> 1 Cl 3:4; 5:4; 45:4; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄ. συγγραφή\" data-meanings=\"escritura/documento injusto\">ἄ. συγγραφή</span> B 3:3 (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/ISA.58.6\" target=\"_blank\" rel=\"noopener noreferrer\">Is 58.6</a>); <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οὐδὲν ἄ.\" data-meanings=\"nada injusto\">οὐδὲν ἄ.</span> 1 Cl 45:3. — Bibliografia, veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀδικία\" data-meanings=\"injustiça\">ἀδικία</span>. — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"δίκη\" data-meanings=\"justiça\">δίκη</span>. M-M. TW.\n</p></section></article><article id=\"entry-adikos-adv-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀδίκως</h1><div class=\"entry-meta\"><span>advérbio</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦adíkōs⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\nAdvérbio de <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄδικος\" data-meanings=\"injusto\">ἄδικος</span> (Ésquilo, Heródoto+), <strong>injustamente</strong> (oposto a <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"δικαίως\" data-meanings=\"justamente\">δικαίως</span>): B 5:4 (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PRO.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">Pv 1.17</a>); <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"μισεῖν τινα ἀ.\" data-meanings=\"odiar alguém injustamente\">μισεῖν τινα ἀ.</span> 1 Cl 60:3. Também <strong>imerecidamente</strong>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πάσχων ἀ.\" data-meanings=\"sofrendo injustamente\">πάσχων ἀ.</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pe 2.19</a>. O v. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">23</a> tem a v.l. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τῷ κρίνοντι ἀδίκως\" data-meanings=\"ao que julga injustamente\">τῷ κρίνοντι ἀδίκως</span> (aplicada a Pilatos; defendida por Harnack, <em>Beiträge</em> VII 1916, p. 89 s.; veja U. Holzmeister, comentário pp. 270 ss.; E. Selwyn, <em>1 Peter</em>, 1958 ad loc.). — TW.\n</p></section></article><article id=\"entry-adistaktos-adv-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀδιστάκτως</h1><div class=\"entry-meta\"><span>advérbio de <span class=\"greek\">ἀδίστακτος</span></span><span class=\"separator\">·</span><span class=\"transliteration\">⟦adistáktōs⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\nAdvérbio de <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀδίστακτος\" data-meanings=\"indubitável; sem hesitação\">ἀδίστακτος</span>.\n<span class=\"sense-number\">1.</span> Ativamente, <strong>sem duvidar, sem hesitar</strong> (Philod., <em>Rhet.</em> I 133 Sudh.): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἰτεῖσθαι\" data-meanings=\"pedir\">αἰτεῖσθαι</span>, “pedir confiadamente”, Hm 9:2, 4, 6. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐπιχορηγεῖν πάντα τῷ πένητι\" data-meanings=\"prover tudo ao pobre\">ἐπιχορηγεῖν πάντα τῷ πένητι</span>, “prover tudo ao pobre sem hesitar = sem pensar duas vezes”, Hs 2:5; compare 7; 9, 24, 2 (com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀνονειδίστως\" data-meanings=\"sem censura; sem recriminação\">ἀνονειδίστως</span>). <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"παρέχεσθαι τῷ πένητι\" data-meanings=\"dar ao pobre\">παρέχεσθαι τῷ πένητι</span> Hs 2:7. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τοῖς αἰτουμένοις διδόναι\" data-meanings=\"dar aos que pedem\">τοῖς αἰτουμένοις διδόναι</span> Hs 5, 4, 4 (v.l. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀδιαλείπτως\" data-meanings=\"incessantemente\">ἀδιαλείπτως</span>). <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"μετανοεῖν\" data-meanings=\"arrepender-se\">μετανοεῖν</span>, “arrepender-se sem demora”, Hs 8, 10, 3.\n<span class=\"sense-number\">2.</span> Passivamente, <strong>além de dúvida, seguramente</strong> (Apollon. Dysc., <em>Gramm. Graeci</em> II 2 p. 213, 5 U.; <em>Anth. Pal.</em> 12, 151; PGM 4, 2511): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οἵ τοιοῦτοι οὖν ἀ. κατοικήσουσιν ἐν τῇ βασιλείᾳ τοῦ θεοῦ\" data-meanings=\"tais pessoas certamente habitarão no reino de Deus\">οἵ τοιοῦτοι οὖν ἀ. κατοικήσουσιν ἐν τῇ βασιλείᾳ τοῦ θεοῦ</span>, Hs 9, 29, 2. — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"δίς\" data-meanings=\"duas vezes\">δίς</span>.\n</p></section></article><article id=\"entry-admin-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἀδμίν</h1><div class=\"entry-meta\"><span class=\"article greek\">ὁ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦Admín⟧</span><span class=\"separator\">·</span><span>indeclinável</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n<strong>Admin</strong>, filho de Arni, na genealogia de Jesus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.33\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 3.33</a> (o nome falta, seja por omissão, seja por substituição, nas variantes textuais).\n</p></section></article><article id=\"entry-adokimos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀδόκιμος</h1><div class=\"entry-meta\"><span class=\"greek\">ον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦adókimos⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Demócrito e outros; também Polyb. 6, 25, 8; 16, 14, 9; inscrições, papiros; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PRO.25.4\" target=\"_blank\" rel=\"noopener noreferrer\">Pv 25.4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/ISA.1.22\" target=\"_blank\" rel=\"noopener noreferrer\">Is 1.22</a>) literalmente <strong>“não aprovado no teste”</strong>; depois, sem qualificação, <strong>sem valor, indigno, reprovado</strong>, de pessoas (X., <em>De Rep. Lac.</em> 3, 3; Plut., <em>Mor.</em> 4c <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀνθρώποις ἀδοκίμοις ἐγχειρίζουσι τ. παῖδας\" data-meanings=\"confiam os filhos a homens sem valor\">ἀνθρώποις ἀδοκίμοις ἐγχειρίζουσι τ. παῖδας</span>; Herodian 7, 7, 5; Jos., <em>C. Ap.</em> 2, 236 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀ. σοφισταί\" data-meanings=\"sofistas sem valor\">ἀ. σοφισταί</span>; Did., <em>Gen.</em> 122, 6) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.27\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 9.27</a>; ITr 12:3; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.13.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Co 13.5–7</a> (sobre a autoafirmação, compare Demosth. 18, 111); <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀνὴρ ἀ. ἀπείραστος\" data-meanings=\"um homem não provado é um homem não testado\">ἀνὴρ ἀ. ἀπείραστος</span>, Agr 21. Com indicação do aspecto em que o teste não é superado: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀδόκιμοι περὶ τὴν πίστιν\" data-meanings=\"reprovados quanto à fé\">ἀδόκιμοι περὶ τὴν πίστιν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Tm 3.8</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πρὸς πᾶν ἔργον ἀγαθὸν ἀ.\" data-meanings=\"impróprios para toda boa obra\">πρὸς πᾶν ἔργον ἀγαθὸν ἀ.</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">Tt 1.16</a>. — De coisas (Fílon, <em>Conf. Lingu.</em> 198; PCairZen 176, 64 [séc. III a.C.], de dinheiro), <strong>solo improdutivo</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.8\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6.8</a>. Da <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"νοῦς\" data-meanings=\"mente\">νοῦς</span> gentílica, em jogo de palavras com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οὐ δοκιμάζειν\" data-meanings=\"não aprovar\">οὐ δοκιμάζειν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.28\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 1.28</a>. — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"δοκάω\" data-meanings=\"parecer; julgar\">δοκάω</span>. TW. Spicq.\n</p></section></article><article id=\"entry-adolos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄδολος</h1><div class=\"entry-meta\"><span class=\"greek\">ον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦ádolos⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n“<strong>Sem dolo</strong>” (Píndaro e outros, mas sobretudo em sentido ativo, “honesto”; assim também como advérbio em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/WIS.7.13\" target=\"_blank\" rel=\"noopener noreferrer\">Sb 7.13</a> e Jos., <em>Ant.</em> 1, 212; Just., <em>D.</em> 125, 1 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀδόλως\" data-meanings=\"sem dolo; honestamente\">ἀδόλως</span>); em sentido passivo, <strong>não adulterado, puro</strong> (especialmente em papiros e inscrições desde o séc. III a.C.; por exemplo PHib 85, 16 s. [261 a.C.]; 98, 19 [261 a.C.]; POxy 729, 19; BGU 290, 13; 1005, 5; 1015, 13; PTebt 105; SIG 736, 100; Fílon, <em>Rer. Div. Her.</em> 95), de leite, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pe 2.2</a>. — F. Dölger, <em>Ac</em> I, 1929, p. 170, 39. — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"δόλος\" data-meanings=\"dolo; engano\">δόλος</span>. M-M.\n</p></section></article><article id=\"entry-adoxos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄδοξος</h1><div class=\"entry-meta\"><span class=\"greek\">ον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦ádoxos⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n<strong>Sem reputação, obscuro</strong> (TGF p. 921, <em>adespota</em> nº 423; Xenofonte+; OGI 5, 63 s. [311 a.C.]; POxy 79 II, 4 [séc. II d.C.]; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/SIR.10.31\" target=\"_blank\" rel=\"noopener noreferrer\">Eclo 10.31</a>; Jos., <em>Vi.</em> 278; Just.) 1 Cl 3:3; MPol 8:1 (em ambos os casos, oposto a <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἔνδοξος\" data-meanings=\"honrado; reputado\">ἔνδοξος</span>, como Just., <em>D.</em> 32, 1; Ael. Aristid. 26, 39 K. = 14 p. 338 D.; Diog. L. 7, 117). — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"δοκάω\" data-meanings=\"parecer; julgar\">δοκάω</span>.\n</p></section></article><article id=\"entry-adramyttenos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἀδραμυττηνός</h1><div class=\"entry-meta\"><span class=\"greek\">ή, όν</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦Adramuttēnós⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"Ἁδραμυντηνός\" data-meanings=\"variante ortográfica\">Ἁδραμυντηνός</span> W-H.; sobre a grafia, veja Stephan. Byz. s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"Ἀδραμύττειον\" data-meanings=\"Adramítio\">Ἀδραμύττειον</span>; B-D-F §42, 3; Rob. 210; 223) <strong>de Adramítio</strong> (<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"Ἀτραμύττειον\" data-meanings=\"Adramítio; forma antiga\">Ἀτραμύττειον</span> Hdt. 7, 42 e outros; mais tarde <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"Ἀδραμύττειον\" data-meanings=\"Adramítio\">Ἀδραμύττειον</span>. O adjetivo, por exemplo, Strabo 13, 1, 61; 62; Plut., <em>Cic.</em> 862 [4, 5]; OGI 238, 4), porto marítimo da Mísia, no noroeste da Ásia Menor, junto ao mar Egeu, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.2\" target=\"_blank\" rel=\"noopener noreferrer\">At 27.2</a>. Veja R. Harris, “Adramyttium (Ac 27:2)”, <em>Contemp. Rev.</em> 128, 1925, 194–202.\n</p></section></article><article id=\"entry-adranes-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀδρανής</h1><div class=\"entry-meta\"><span class=\"greek\">ές</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦adranḗs⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"δραίνω\" data-meanings=\"estar pronto para fazer; ter força\">δραίνω</span> = “estar pronto para agir, ter força”; Posidipo [c. 280 a.C.]; <em>Anth. Pal.</em> 9, 359; Plut.; Dio Chrys. 11 [12], 31; Philostrat., <em>Vi. Apoll.</em> 3, 39; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/WIS.13.19\" target=\"_blank\" rel=\"noopener noreferrer\">Sb 13.19</a>) <strong>sem força, impotente</strong> (com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀδύνατος\" data-meanings=\"incapaz; impotente\">ἀδύνατος</span>; compare Proclus, <em>Theol.</em> 149 p. 130, 25), <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πνεύματα ἐπίγεια ἀ.\" data-meanings=\"espíritos terrenos impotentes\">πνεύματα ἐπίγεια ἀ.</span> Hm 11:19. — DELG s.v. 1. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"δράω\" data-meanings=\"fazer; agir\">δράω</span>.\n</p></section></article><article id=\"entry-adrias-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἀδρίας</h1><div class=\"entry-meta\"><span class=\"greek\">ου, ὁ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦Adrías⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Heródoto e outros; inscrições desde 325 a.C., Meisterhans³-Schw.; B-D-F §261, 8) <strong>mar Adriático</strong> (incluía-se nele o mar entre Creta e Sicília: Eudoxo [séc. III a.C.], 79 Fgm. 1 Jac.; Ptolem. 3, 4, 1; 17, 1; Ael. Aristid. 48, 66 K. = 24 p. 483 D.; Jos., <em>Vi.</em> 15), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.27\" target=\"_blank\" rel=\"noopener noreferrer\">At 27.27</a>. Warnecke, <em>Romfahrt</em> 69–74.\n</p></section></article><article id=\"entry-hadrotes-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἁδρότης</h1><div class=\"entry-meta\"><span class=\"greek\">ητος, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦hadrótēs⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(<em>Il.</em> 24, 6; Teofrasto e Epicuro [Diog. L. 10, 83]) <strong>abundância</strong>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐν τῇ ἁ. ταύτῃ\" data-meanings=\"nesta abundância; nesta dádiva generosa\">ἐν τῇ ἁ. ταύτῃ</span>, “nesta dádiva abundante” (a coleta feita em favor de Jerusalém), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.20\" target=\"_blank\" rel=\"noopener noreferrer\">2 Co 8.20</a>. — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἅδην\" data-meanings=\"em abundância\">ἅδην</span>. M-M.\n</p></section></article><article id=\"entry-adunateo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀδυνατέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦adunatéō⟧</span><span class=\"separator\">·</span><span class=\"greek\">fut. ἀδυνατήσω</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\nLiteralmente <strong>“estar sem força, ser incapaz”</strong> (assim desde Epicarmo [? c. 480 a.C.], Fgm. 266, que o usa pessoalmente [Vorsokrat.⁵ 23 B, 23 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀδυνατεῖ δ’ οὐδὲν θεός\" data-meanings=\"para Deus nada é impossível\">ἀδυνατεῖ δ’ οὐδὲν θεός</span>]; também PEnteux 26, 3 [séc. III a.C.]; UPZ 110, 13 e 89 [164 a.C.]; 6, 36 [163 a.C.] e outros; Herm. Wr. 10, 18; Fílon; Jos., <em>Ant.</em> 15, 211; Ar. 3, 2; Tat. 16, 2; Ath. 21, 2; <em>R.</em> 57, 27); no NT apenas impessoalmente (Philod., <em>Ira</em> p. 98 W.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/JOB.10.13\" target=\"_blank\" rel=\"noopener noreferrer\">Jó 10.13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/JOB.42.2\" target=\"_blank\" rel=\"noopener noreferrer\">42.2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/2CH.14.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cr 14.10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/WIS.13.16\" target=\"_blank\" rel=\"noopener noreferrer\">Sb 13.16</a>), <strong>ser impossível</strong>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οὐδὲν ἀδυνατήσει ὑμῖν\" data-meanings=\"nada vos será impossível\">οὐδὲν ἀδυνατήσει ὑμῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17.20</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οὐκ ἀδ. παρὰ τοῦ θεοῦ … πᾶν ῥῆμα\" data-meanings=\"nenhuma palavra será impossível da parte de Deus\">οὐκ ἀδ. παρὰ τοῦ θεοῦ … πᾶν ῥῆμα</span>, v.l. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"παρὰ τῷ θεῷ\" data-meanings=\"junto de Deus\">παρὰ τῷ θεῷ</span>, “nada será impossível para Deus”, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1.37</a> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/GEN.18.14\" target=\"_blank\" rel=\"noopener noreferrer\">Gn 18.14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/DEU.17.8\" target=\"_blank\" rel=\"noopener noreferrer\">Dt 17.8</a>). A ideia de que nada é impossível aos deuses encontra-se também entre os gregos desde época antiga: <em>Od.</em> 16, 211 s.; Hes., <em>Works</em> 5 s.; Alceu 78, 7 Diehl [34, 7 L.-P.]. — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"δύναμαι\" data-meanings=\"poder; ser capaz\">δύναμαι</span>. M-M. TW.\n</p></section></article><article id=\"entry-adunatos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀδύνατος</h1><div class=\"entry-meta\"><span class=\"greek\">ον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦adúnatos⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n<span class=\"sense-number\">1.</span> <strong>Relativo a não possuir capacidade para funcionar adequadamente, impotente, incapaz</strong> (desde Epicarmo).\n<strong>a.</strong> Como adjetivo, de seres espirituais, Hm 11:19c. Com dativo: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀνὴρ ἀ. τοῖς ποσίν\" data-meanings=\"homem incapaz quanto aos pés\">ἀνὴρ ἀ. τοῖς ποσίν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.8\" target=\"_blank\" rel=\"noopener noreferrer\">At 14.8</a> (compare PLond 678, 6 [99/98 a.C.] <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀ. ὄμμασι\" data-meanings=\"incapaz quanto aos olhos\">ἀ. ὄμμασι</span>; também PStras 81, 17 [séc. II a.C.]; PAdl Gk. 17, 5 [séc. I a.C.]; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/TOB.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">Tb 2.10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/TOB.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">5.10</a>).\n<strong>b.</strong> Como substantivo, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οἱ ἀδύνατοι\" data-meanings=\"os incapazes; os fracos\">οἱ ἀδύνατοι</span> (Hyperid. 2, 10, em contraste com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"δυνάμενοι εἰπεῖν\" data-meanings=\"os capazes de falar\">δυνάμενοι εἰπεῖν</span>; TestJob 45:2 [com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πτωχοί\" data-meanings=\"pobres\">πτωχοί</span> em sentido geral]), dos <strong>fracos na fé</strong> (oposto a <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οἱ δυνατοί\" data-meanings=\"os fortes\">οἱ δυνατοί</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.1\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 15.1</a>. — <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὰ ἀδύνατα\" data-meanings=\"as coisas impotentes; aquilo que é incapaz\">τὰ ἀδύνατα</span> Dg 9:6b. — <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὸ ἀδύνατον\" data-meanings=\"a incapacidade\">τὸ ἀδύνατον</span> <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εἰς τὸ τυχεῖν\" data-meanings=\"para alcançar\">εἰς τὸ τυχεῖν</span> 6a; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὸ καθ’ ἑαυτοὺς ἀδύνατον εἰσελθεῖν\" data-meanings=\"nossa própria incapacidade de entrar\">τὸ καθ’ ἑαυτοὺς ἀδύνατον εἰσελθεῖν</span> 9:1. Compare <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"δύναμαι\" data-meanings=\"poder; ser capaz\">δύναμαι</span> com negação.\n<span class=\"sense-number\">2.</span> <strong>Incapaz de acontecer ou ser feito, impossível</strong> (Píndaro, Heródoto e outros; LXX, Fílon, Josefo; Ar. 5, 2; Just.; Tat. 20, 2; Ath.).\n<strong>a.</strong> Adjetivo, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀ.\" data-meanings=\"impossível\">ἀ.</span> com e sem <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐστίν\" data-meanings=\"é\">ἐστίν</span> (B-D-F §127, 2), “é impossível”, Hm 11:19ab; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"παρὰ ἀνθρώποις τοῦτο ἀ. ἐστιν\" data-meanings=\"para os seres humanos isto é impossível\">παρὰ ἀνθρώποις τοῦτο ἀ. ἐστιν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19.26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 10.27</a> (compare Fílon, <em>Spec. Leg.</em> 1, 282; Jos., <em>Ant.</em> 10, 196; PCairZen 31, 8 [séc. III a.C.]; inscrição dedicatória da Frígia em Steinleitner 59, nº 31, 4 s.: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"Μητρὶ Λητῷ ὅτι ἐξ ἀδυνάτων δυνατὰ ποιεῖ\" data-meanings=\"à Mãe Leto, porque torna possíveis as coisas impossíveis\">Μητρὶ Λητῷ ὅτι ἐξ ἀδυνάτων δυνατὰ ποιεῖ</span>; Ps.-Lucian, <em>Halc.</em> 3, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀδύνατος\" data-meanings=\"impossível\">ἀδύνατος</span> e <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"δυνατός\" data-meanings=\"possível\">δυνατός</span> daquilo que Deus não pode e pode fazer); <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οὐδὲν ἀ. παρὰ τῷ θεῷ\" data-meanings=\"nada é impossível para Deus\">οὐδὲν ἀ. παρὰ τῷ θεῷ</span> 1 Cl 27:2 (compare Píndaro, <em>P.</em> 10, 48–50); compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 18.27</a>. Com infinitivo seguinte e acusativo com infinitivo (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/WIS.16.15\" target=\"_blank\" rel=\"noopener noreferrer\">Sb 16.15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/2MA.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">2 Mc 4.6</a>; Jos., <em>Ant.</em> 5, 109; Ar., Just., Ath.), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.4\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6.4</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.18\" target=\"_blank\" rel=\"noopener noreferrer\">18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.4\" target=\"_blank\" rel=\"noopener noreferrer\">10.4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.6\" target=\"_blank\" rel=\"noopener noreferrer\">11.6</a>; Hs 9, 26, 6; MPol 6:1. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οὐκ ἔστιν ἀ. ὑπὲρ ὀνόματος θεοῦ\" data-meanings=\"não é impossível por causa do nome de Deus\">οὐκ ἔστιν ἀ. ὑπὲρ ὀνόματος θεοῦ</span> (subentenda-se <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τοῦτο ποιεῖν\" data-meanings=\"fazer isto\">τοῦτο ποιεῖν</span>) IPhld 10:2.\n<strong>b.</strong> Como substantivo (B-D-F §263, 2; Rob. 372; Mitt-Wilck. II/2, 372 V, 24: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐπιχειρεῖς τοῖς ἀδυνάτοις\" data-meanings=\"empreendes coisas impossíveis\">ἐπιχειρεῖς τοῖς ἀδυνάτοις</span>; Jos., <em>Ant.</em> 11, 195; Tat. 20, 2 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὸ ἀ. τῆς θεορίας\" data-meanings=\"a impossibilidade da contemplação\">τὸ ἀ. τῆς θεορίας</span>; Ath. 23, 5; 30, 1): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὸ ἀ. τοῦ νόμου\" data-meanings=\"aquilo que era impossível para a lei\">τὸ ἀ. τοῦ νόμου</span>, “o que era impossível para a lei [Deus fez]”, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 8.3</a>. — M-M. TW. Spicq. Veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀδυνατέω\" data-meanings=\"ser impossível; ser incapaz\">ἀδυνατέω</span>.\n</p></section></article><article id=\"entry-adusbastaktos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀδυσβάστακτος</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦adusbástaktos⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(<em>hapax legomenon</em>) <strong>não demasiado difícil de suportar</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23.4</a> D* (provavelmente por erro em lugar de <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"δυσβάστακτος\" data-meanings=\"difícil de suportar\">δυσβάστακτος</span>). Veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"βαστάζω\" data-meanings=\"carregar; suportar\">βαστάζω</span>.\n</p></section></article><article id=\"entry-ado-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ᾂδω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦àdō⟧</span><span class=\"separator\">·</span><span class=\"greek\">fut. ᾂσω e ᾂσομαι; 1 aor. ᾖσα</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Desde Homero, mas ali na forma não contraída <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀείδω\" data-meanings=\"cantar\">ἀείδω</span>; inscrições, papiros, LXX; TestSol 8:2 D; TestAbr B, 3, p. 107, 8 [Stone p. 62]; ParJer 7:34; Just., <em>D.</em> 74, 3; Tat.) Fut. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ᾂσω\" data-meanings=\"cantarei\">ᾂσω</span> e <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ᾂσομαι\" data-meanings=\"cantarei\">ᾂσομαι</span> LXX; 1 aor. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ᾖσα\" data-meanings=\"cantei\">ᾖσα</span> (LXX; Mel. [?], PBodm 12). <strong>Cantar, cantar em louvor.</strong>\nAbsolutamente, com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"χορεύειν\" data-meanings=\"dançar em coro\">χορεύειν</span> e <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὀρχεῖσθαι\" data-meanings=\"dançar\">ὀρχεῖσθαι</span>, Hs 9, 11, 5. Com dativo de pessoa (LXX; Philostrat., <em>Imag.</em> 1, 11, 780; Heliod. 5, 15, 3 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐμβατήρια ᾂδ. τ. Διονύσῳ\" data-meanings=\"cantar cantos de marcha a Dioniso\">ἐμβατήρια ᾂδ. τ. Διονύσῳ</span>; compare Diod S 2, 47, 3 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὕμνους λέγειν τῷ θεῷ\" data-meanings=\"proferir hinos ao deus\">ὕμνους λέγειν τῷ θεῷ</span>; Nägeli 42 s.): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ᾂ. διὰ Ἰ. Χρ. τῷ πατρί\" data-meanings=\"cantar ao Pai por meio de Jesus Cristo\">ᾂ. διὰ Ἰ. Χρ. τῷ πατρί</span> IEph 4:2; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τῷ πατρὶ ἐν Χρ. Ἰ.\" data-meanings=\"ao Pai em Cristo Jesus\">τῷ πατρὶ ἐν Χρ. Ἰ.</span> IRo 2:2; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ᾂ. ἐν ταῖς καρδίαις ὑμῶν τ. θεῷ\" data-meanings=\"cantar a Deus em vossos corações\">ᾂ. ἐν ταῖς καρδίαις ὑμῶν τ. θεῷ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 3.16</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ᾂδοντες καὶ ψάλλοντες … τῇ καρδίᾳ ὑμῶν τῷ κυρίῳ\" data-meanings=\"cantando e salmodiando de coração ao Senhor\">ᾂδοντες καὶ ψάλλοντες … τῇ καρδίᾳ ὑμῶν τῷ κυρίῳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 5.19</a> — “cantando e tocando [instrumentalmente] de coração ao Senhor” (Mft.; diferentemente NRSV; V. Matthews, ABD IV 934; para Qumran veja Schürer II 290 s.; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.5.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 5.8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.14.2\" target=\"_blank\" rel=\"noopener noreferrer\">14.2 s.</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.15.2\" target=\"_blank\" rel=\"noopener noreferrer\">15.2 s.</a>).\nCom acusativo seguinte, da canção cantada (Polycrates, 588 Fgm. 1 Jac.; Jos., <em>Ant.</em> 3, 64 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὕμνους\" data-meanings=\"hinos\">ὕμνους</span>): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ᾠδὴν καινήν\" data-meanings=\"um cântico novo\">ᾠδὴν καινήν</span> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PSA.143.9\" target=\"_blank\" rel=\"noopener noreferrer\">Sl 143.9</a>; compare Fílon, <em>Mos.</em> 1, 255 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ᾂ. ᾆσμα καινόν\" data-meanings=\"cantar um cântico novo\">ᾂ. ᾆσμα καινόν</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 5.9</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὡς ᾠδὴν καινήν\" data-meanings=\"como um cântico novo\">ὡς ᾠδὴν καινήν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.14.3\" target=\"_blank\" rel=\"noopener noreferrer\">14.3</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὴν ᾠδὴν Μωυσέως\" data-meanings=\"o cântico de Moisés\">τὴν ᾠδὴν Μωυσέως</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.15.3\" target=\"_blank\" rel=\"noopener noreferrer\">15.3</a> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/DEU.31.30\" target=\"_blank\" rel=\"noopener noreferrer\">Dt 31.30</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/EXO.15.1\" target=\"_blank\" rel=\"noopener noreferrer\">Êx 15.1</a>); <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἴσω ᾠδὴν ἁγίαν Κυρίῳ τῷ θεῷ μου\" data-meanings=\"cantarei um cântico santo ao Senhor meu Deus\">αἴσω ᾠδὴν ἁγίαν Κυρίῳ τῷ θεῷ μου</span> GJs 6:3.\nPassivo: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"Ἰησοῦς Χριστὸς ᾂδεται\" data-meanings=\"Jesus Cristo é cantado/louvado\">Ἰησοῦς Χριστὸς ᾂδεται</span>, “o louvor de Jesus Cristo está sendo cantado”, IEph 4:1. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ᾂδω τὰς ἐκκλησίας\" data-meanings=\"canto as igrejas\">ᾂδω τὰς ἐκκλησίας</span>, “canto o louvor das igrejas”, IMg 1:2. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"φόβος νόμου ᾂδεται\" data-meanings=\"o temor da lei é cantado\">φόβος νόμου ᾂδεται</span> Dg 11:6; mas compare Fílon, <em>Sacr. Abel.</em> 131 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"λόγος ᾂδεται\" data-meanings=\"uma doutrina é apresentada\">λόγος ᾂδεται</span>; Aelian, <em>NA</em> 17, 5 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"Φύλαρχος ᾂδει …\" data-meanings=\"Filarco diz/proclama…\">Φύλαρχος ᾂδει …</span>; Arrian, <em>Anab.</em> 4, 9, 5, “proclamar”. Semelhantemente Epict., <em>Gnomolog.</em> 26 [Fgm. Stob.] <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ᾂδειν τὰ λόγια\" data-meanings=\"proclamar os oráculos\">ᾂδειν τὰ λόγια</span>; Plut., <em>Thes.</em> 8 [19, 1]; Maximus Tyr. 32, 1b.\n— J. Kroll, <em>D. christl. Hymnodik bis zu Klemens v. Al.</em>, suplemento ao programa de cursos de Braunsberg, SS. 1921 e WS. 1921/22; V. Matthews (acima, com bibliografia). — B. 1249. DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀείδω\" data-meanings=\"cantar\">ἀείδω</span>. M-M. TW.\n</p></section></article>"};
